/// Counts the number of `true` entries in a boolean slice.
pub fn count_true(condition: &[bool]) -> usize {
    condition.iter().filter(|&&b| b).count()
}

/// Returns a new Vec containing exactly those elements of `arr`
/// whose corresponding entries in `condition` are `true`,
/// preserving relative order.
///
/// Assumes `condition.len() == arr.len()`.
pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    debug_assert_eq!(
        condition.len(),
        arr.len(),
        "condition and arr must have the same length"
    );

    let n_true = count_true(&condition);

    let mut result = Vec::with_capacity(n_true);
    for (keep, value) in condition.into_iter().zip(arr.into_iter()) {
        if keep {
            result.push(value);
        }
    }

    // Verification: output length must equal the number of `true` values.
    debug_assert_eq!(
        result.len(),
        n_true,
        "result length must equal the number of true values in condition"
    );

    result
}

